-- Verificación: filas por tabla
SELECT 'estudiantes' AS tabla, COUNT(*) AS filas FROM estudiantes UNION ALL SELECT 'acudientes', COUNT(*) FROM acudientes
UNION ALL SELECT 'profesores', COUNT(*) FROM profesores UNION ALL SELECT 'materias', COUNT(*) FROM materias
UNION ALL SELECT 'registros_academicos', COUNT(*) FROM registros_academicos UNION ALL SELECT 'pagos', COUNT(*) FROM pagos
UNION ALL SELECT 'clubes', COUNT(*) FROM clubes UNION ALL SELECT 'recursos', COUNT(*) FROM recursos;
